// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 g) public {
        vm.assume(actor != address(c) && actor != address(this));
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        // fund the contract so a winning settle could pay out (removes balance revert noise)
        vm.deal(address(c), 2 ether);

        // advance exactly one block: in the reference, the stored block is the NEXT block,
        // so settle() at block.number == stored block must revert for every actor/hash.
        vm.roll(block.number + 1);

        vm.prank(actor);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}
